class SubrectangleQueries {
    private final int[][] rectangle;
    public SubrectangleQueries(int[][] rectangle){
        this.rectangle=new int[rectangle.length][];
        for(int i=0;i<rectangle.length;i++)this.rectangle[i]=rectangle[i].clone();
    }
    public void updateSubrectangle(int row1,int col1,int row2,int col2,int newValue){
        for(int row=row1;row<=row2;row++)for(int col=col1;col<=col2;col++)rectangle[row][col]=newValue;
    }
    public int getValue(int row,int col){
        return rectangle[row][col];
    }
}

code.kotlin:
class SubrectangleQueries(rectangle:Array<IntArray>){
    private val rectangle=Array(rectangle.size){
        rectangle[it].copyOf()
    };
    fun updateSubrectangle(row1:Int,col1:Int,row2:Int,col2:Int,newValue:Int){
        for(row in row1..row2)for(col in col1..col2)rectangle[row][col]=newValue
    };
    fun getValue(row:Int,col:Int):Int=rectangle[row][col]
}

